import{_ as d}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as c,a as m,b as g,c as u,d as h,e as b,f,g as t,h as v,i as s,j as r,k as z,l as x,m as y,n as k,o as n,p as _,q as F,r as P,s as q,t as w,u as I,v as D,w as o,x as C,y as A,z as L,A as S,B as M,C as E,D as N,E as B,F as G,G as V,H as R,I as T,J as O,K as U}from"./chunks/M-S-DS6aa7.CdBISpqM.js";import{_ as $}from"./chunks/M-S-DS2l2.BdmWUi3X.js";import{_ as Y}from"./chunks/M-S-SW8c.OZF8VB_x.js";import{_ as p}from"./chunks/OFF.BrU7kQE-.js";import{_ as a}from"./chunks/EN.P9aPnFBv.js";import{_ as e}from"./chunks/ON.DXVlsWbj.js";import{_ as i}from"./chunks/DIS.DdpTdGGD.js";import{_ as Q}from"./chunks/M-S-PS5b.B4zocwby.js";import{_ as W,o as H,c as Z,a3 as J}from"./chunks/framework.g9mfNVRQ.js";const ui=JSON.parse('{"title":"Visualizzazione","description":"","frontmatter":{"source_hash":"d238ff7b1e","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/use/display.md","filePath":"it/use/display.md"}'),j={name:"it/use/display.md"};function K(X,l,ii,ai,ei,oi){return H(),Z("div",null,[...l[0]||(l[0]=[J('<div class="admonition xdrip"><p class="admonition-title"><img src="'+d+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_chart_areaspline_grey600_48dp.png" style="width:5%;"> xDrip+ impostazioni di visualizzazione</p></div><p>Questo menu ti permette di personalizzare molti aspetti visivi di xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">xDrip+ impostazioni di visualizzazione</p><p> Personalizzazioni di visualizzazione</p></div><p><em>Nota: controlla le funzioni delle <a href="#graph-settings">Impostazioni grafico</a> prima di usare le impostazioni dei colori.</em></p><h3 id="color-settings" tabindex="-1">Impostazioni colore <a class="header-anchor" href="#color-settings" aria-label="Permalink to &quot;Impostazioni colore {#color-settings}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">xDrip+ Impostazioni colore</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_palette_grey600_48dp.png" style="width:8%;"> Personalizzazione Colori</p></div><p>Il grafico di esempio in alto mostra l&#39;effetto delle modifiche.</p><div class="admonition xdripitem"><p class="admonition-title">Chart di Esempio</p><p> <img src="'+c+'" style="zoom:75%;"></p></div><p>Quando modifichi un colore puoi scegliere</p><ol><li>tonalità e saturazione</li><li>chiarezza/scurezza</li><li>trasparenza.</li></ol><p>Il risultato viene mostrato a confronto con il colore originale.</p><p>Puoi riportare il colore al valore predefinito o salvarlo.</p><img src="'+m+'" style="zoom:75%;"><h5 id="glucose-values-and-lines" tabindex="-1">Valori di glucosio e linee <a class="header-anchor" href="#glucose-values-and-lines" aria-label="Permalink to &quot;Valori di glucosio e linee {#glucose-values-and-lines}&quot;">​</a></h5><p>Puoi personalizzare il grafico principale della glicemia. I limiti alto e basso sono definiti nelle <a href="./settings.html#glucose-units">impostazioni Unità di misura glicemia.</a></p><p>I colori dei valori alti, nell&#39;intervallo e bassi cambiano il grafico e le linee dei limiti nella schermata principale, nella notifica e nei grafici del widget.</p><div class="admonition xdrip"><p class="admonition-title"><small><small>VALORI DI GLUCOSIO E LINEE</small></small></p><p>Valori Glicemici Elevati<span style="float:right;width:40px;height:40px;background-color:#FFBB33;display:inline-block;"></span></p><p>Valori Glicemici nella media<span style="float:right;width:40px;height:40px;background-color:#33B5E6;display:inline-block;"></span></p><p>Valori Glicemici Bassi<span style="float:right;width:40px;height:40px;background-color:#C30909;display:inline-block;"></span></p><p>Valori Glicemici Errati<span style="float:right;width:40px;height:40px;background-color:#FFFFFF;display:inline-block;"></span></p><p>Valori Filtrati<span style="float:right;width:40px;height:40px;background-color:#A0A0A0;display:inline-block;"></span></p></div><img src="'+g+'" style="zoom:75%;"><p>I valori errati e filtrati sono visibili con i sensori che forniscono dati grezzi.</p><img src="'+u+'" style="zoom:75%;"><h5 id="colors-of-bg-readings-and-trend-arrows" tabindex="-1">Colori del valore di glicemia e delle frecce di tendenza <a class="header-anchor" href="#colors-of-bg-readings-and-trend-arrows" aria-label="Permalink to &quot;Colori del valore di glicemia e delle frecce di tendenza {#colors-of-bg-readings-and-trend-arrows}&quot;">​</a></h5><p>Puoi anche personalizzare il colore del valore di glicemia attuale e della freccia di tendenza in base ai limiti dell&#39;intervallo.</p><img src="'+h+'" style="zoom:75%;"><div class="admonition xdrip"><p class="admonition-title"><small><small>COLORI DEL VALORE DI GLICEMIA E FRECCIA DI TENDENZA</small></small></p><p>Valori Glicemici Elevati<span style="float:right;width:40px;height:40px;background-color:#FFBB33;display:inline-block;"></span></p><p>Valori Glicemici nella media<span style="float:right;width:40px;height:40px;background-color:#FFFFFF;display:inline-block;"></span></p><p>Valori Glicemici Bassi<span style="float:right;width:40px;height:40px;background-color:#C30909;display:inline-block;"></span></p><p>Previsione ipo (critica)<span style="float:right;width:40px;height:40px;background-color:#C30909;display:inline-block;"></span></p></div><p>Previsione ipo (critica) è il colore del messaggio di previsione di glicemia bassa sulla schermata principale quando la glicemia bassa è vicina.</p><h5 id="treatments-and-predictions-curves" tabindex="-1">Curve dei trattamenti e delle previsioni <a class="header-anchor" href="#treatments-and-predictions-curves" aria-label="Permalink to &quot;Curve dei trattamenti e delle previsioni {#treatments-and-predictions-curves}&quot;">​</a></h5><ol><li>Insulina attiva (curva principale dei <a href="./mainUI.html#units-of-insulin">trattamenti</a>)</li><li>Attività dell&#39;insulina (piccola linea tratteggiata)</li></ol><div class="admonition xdrip"><p class="admonition-title"><small><small>TERAPIA / CURVE DI PREVISIONE</small></small></p><p>Colori Terapia<span style="float:right;width:40px;height:40px;background-color:#77AA00;display:inline-block;"></span></p><p>Colori Scuri Terapia<span style="float:right;width:40px;height:40px;background-color:#334400;display:inline-block;"></span></p></div><img src="'+b+'" style="zoom:75%;"><ol><li><a href="./predictions.html">Previsione</a> della glicemia (grafico principale delle previsioni)</li><li><a href="./mainUI.html#grams-of-carbs">Carboidrati</a> attivi (piccola linea tratteggiata)</li></ol><div class="admonition xdrip"><p class="admonition-title"><small><small>TERAPIA / CURVE DI PREVISIONE</small></small></p><p>Colori Previsione<span style="float:right;width:40px;height:40px;background-color:#AA66CC;display:inline-block;"></span></p><p>Colori Scuri previsione<span style="float:right;width:40px;height:40px;background-color:#7700AA;display:inline-block;"></span></p></div><img src="'+f+'" style="zoom:75%;"><h5 id="average-and-target-lines" tabindex="-1">Linee della media e del target <a class="header-anchor" href="#average-and-target-lines" aria-label="Permalink to &quot;Linee della media e del target {#average-and-target-lines}&quot;">​</a></h5><ol><li>Linea della media delle 8 ore</li><li>Linea della media delle 24 ore</li><li>Linea del target</li></ol><div class="admonition xdrip"><p class="admonition-title"><small><small>LINEE MEDIANA E DI TARGET</small></small></p><p>Linea Media 8 ore<span style="float:right;width:40px;height:40px;background-color:#558800;display:inline-block;"></span></p><p>Linea Media 24 ore<span style="float:right;width:40px;height:40px;background-color:#C56F9D;display:inline-block;"></span></p><p>Glucosio linea di destinazione<span style="float:right;width:40px;height:40px;background-color:#A4A409;display:inline-block;"></span></p></div><img src="'+t+'" style="zoom:75%;"><h5 id="annotations-and-dots" tabindex="-1">Note e punti <a class="header-anchor" href="#annotations-and-dots" aria-label="Permalink to &quot;Note e punti {#annotations-and-dots}&quot;">​</a></h5><p><a href="./mainUI.html#treatments">Misure capillari (anche calibrazioni) e trattamenti.</a></p><div class="admonition xdrip"><p class="admonition-title"><small><small>NOTE E PUNTI</small></small></p><p>Misurazioni Glicemia in Secondo Piano<span style="float:right;width:40px;height:40px;background-color:#FFFFFF;display:inline-block;"></span></p><p>Misurazioni Glicemia in Primo Piano<span style="float:right;width:40px;height:40px;background-color:#FF4444;display:inline-block;"></span></p><p>Terapia in Secondo Piano<span style="float:right;width:40px;height:40px;background-color:#FFFFFF;display:inline-block;"></span></p><p>Terapia in Primo Piano<span style="float:right;width:40px;height:40px;background-color:#77AA00;display:inline-block;"></span></p></div><h5 id="" tabindex="-1">{#} <a class="header-anchor" href="#" aria-label="Permalink to &quot;{#}&quot;">​</a></h5><img src="'+v+'" style="zoom:75%;"><h5 id="backgrounds" tabindex="-1">Sfondi <a class="header-anchor" href="#backgrounds" aria-label="Permalink to &quot;Sfondi {#backgrounds}&quot;">​</a></h5><p>Sfondi dei grafici, grafico principale</p><div class="admonition xdrip"><p class="admonition-title"><small><small>SFONDI</small></small></p><p>Diagramma Principale in secondo piano <span style="float:right;width:40px;height:40px;background-color:#212121;border:1px solid #FFFFFF;display:inline-block;"></span></p><p>Notifiche in secondo piano <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#FFFFFF;background-image:linear-gradient(45deg, #888 25%, transparent 25%, transparent 75%, #888 75%, #888), linear-gradient(45deg, #888 25%, transparent 25%, transparent 75%, #888 75%, #888);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p><p>Sfondo grafico Widget <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#4C4C4C;background-image:linear-gradient(45deg, #333 25%, transparent 25%, transparent 75%, #333 75%, #333), linear-gradient(45deg, #333 25%, transparent 25%, transparent 75%, #333 75%, #333);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p></div><p>Esempio: sfondo del grafico nella notifica</p><img src="'+s+'" style="zoom:75%;"><h5 id="plugins-and-features" tabindex="-1">Plugin e funzionalità <a class="header-anchor" href="#plugins-and-features" aria-label="Permalink to &quot;Plugin e funzionalità {#plugins-and-features}&quot;">​</a></h5><p>Se usi un <a href="./../calibrate/advancedcal.html#plugins">plugin</a>, puoi anche visualizzare il valore di glicemia del plugin come grafico secondario.<br> Deve essere attiva la visualizzazione del plugin sul grafico.</p><div class="admonition xdrip"><p class="admonition-title"><small><small>PLUGIN E FUNZIONALITÀ</small></small></p><p>Valore di glicemia del plugin secondario <span style="float:right;width:40px;height:40px;background-color:#292A2B;border:1px solid #FFFFFF;display:inline-block;"></span></p></div><img src="'+$+'" style="zoom:75%;"><p>Se hai i passi e la frequenza cardiaca da un <a href="./../smartwatch/smartwatch.html#smartwatch-sensors">dispositivo indossabile</a>, puoi personalizzare i colori dei grafici.</p><div class="admonition xdrip"><p class="admonition-title"><small><small>PLUGIN E FUNZIONALITÀ</small></small></p><p>Contapassi 1° colore <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#CBE5DF;background-image:linear-gradient(45deg, #6B857F 25%, transparent 25%, transparent 75%, #6B857F 75%, #6B857F), linear-gradient(45deg, #6B857F 25%, transparent 25%, transparent 75%, #6B857F 75%, #6B857F);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p><p>Contapassi 2° colore <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#DEF1F0;background-image:linear-gradient(45deg, #7D908F 25%, transparent 25%, transparent 75%, #7D908F 75%, #7D908F), linear-gradient(45deg, #7D908F 25%, transparent 25%, transparent 75%, #7D908F 75%, #7D908F);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p><p>Cardiofrequenzimetro <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#DADCF9;background-image:linear-gradient(45deg, #707290 25%, transparent 25%, transparent 75%, #707290 75%, #707290), linear-gradient(45deg, #707290 25%, transparent 25%, transparent 75%, #707290 75%, #707290);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p></div><p>Nell&#39;esempio qui sotto: 1. frequenza cardiaca e 2. contapassi.</p><img src="'+Y+'" style="zoom:75%;"><h5 id="basal-and-smb" tabindex="-1">Basale e SMB <a class="header-anchor" href="#basal-and-smb" aria-label="Permalink to &quot;Basale e SMB {#basal-and-smb}&quot;">​</a></h5><p>Se riesci a visualizzare la basale (<a href="#basal-information">da AAPS</a> o con <a href="./predictions.html#basal-profile-editor">impostazione manuale</a>), puoi anche personalizzarne il colore.</p><div class="admonition xdrip"><p class="admonition-title"><small><small>COLORI INSULINA</small></small></p><p>TBR basale <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#558AE4;background-image:linear-gradient(45deg, #3F74CE 25%, transparent 25%, transparent 75%, #3F74CE 75%, #3F74CE), linear-gradient(45deg, #3F74CE 25%, transparent 25%, transparent 75%, #3F74CE 75%, #3F74CE);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p><p>Icona SMB <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#E4DF63;background-image:linear-gradient(45deg, #CEC94D 25%, transparent 25%, transparent 75%, #CEC94D 75%, #CEC94D), linear-gradient(45deg, #CEC94D 25%, transparent 25%, transparent 75%, #CEC94D 75%, #CEC94D);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p><p>Linea SMB <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#7494D4;background-image:linear-gradient(45deg, #5F7FC0 25%, transparent 25%, transparent 75%, #5F7FC0 75%, #5F7FC0), linear-gradient(45deg, #5F7FC0 25%, transparent 25%, transparent 75%, #5F7FC0 75%, #5F7FC0);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p></div><img src="'+r+'" style="zoom:75%;"><p>Gli <a href="#smb">SMB</a> sono icone che alleggeriscono il grafico per i trattamenti con microboli.</p><img src="'+z+'" style="zoom:75%;"><h5 id="flair-colors" tabindex="-1">Colori luminosi <a class="header-anchor" href="#flair-colors" aria-label="Permalink to &quot;Colori luminosi {#flair-colors}&quot;">​</a></h5><p>Se vuoi colorare le barre superiore e inferiore dello schermo Android, attiva i colori luminosi.</p><div class="admonition xdrip"><p class="admonition-title"><small><small>COLORI LUMINOSI</small></small></p><p>Usa colori luminosi <span style="float:right;"><img src="'+p+'" style="zoom:75%;"></span></p><p>Luminosità barra di titolo superiore <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#FFFFFF;background-image:linear-gradient(45deg, #888 25%, transparent 25%, transparent 75%, #888 75%, #888), linear-gradient(45deg, #888 25%, transparent 25%, transparent 75%, #888 75%, #888);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p><p>Luminosità barra inferiore tasti <span style="float:right;width:40px;height:40px;background-color:#000000;border:1px solid #FFFFFF;display:inline-block;"></span></p></div><p>Barra del titolo superiore:</p><img src="'+x+'" style="zoom:75%;"><p>Barra di navigazione inferiore:</p><img src="'+y+'" style="zoom:75%;"><h3 id="font-settings" tabindex="-1">Impostazioni Caratteri <a class="header-anchor" href="#font-settings" aria-label="Permalink to &quot;Impostazioni Caratteri {#font-settings}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Impostazioni Caratteri</p><p> Personalizza Caratteri</p></div><div class="admonition xdripitem"><p class="admonition-title">Ingrandisci caratteri su schermi grandi<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Allarga automaticamente la dimensione dei caratteri su schermi di grande dimensione, come i tablet</p></div><h3 id="language" tabindex="-1">Lingua <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Lingua {#language}&quot;">​</a></h3><p>Per impostazione predefinita xDrip usa la lingua del telefono. Puoi scegliere un&#39;altra lingua per xDrip e forzarne la visualizzazione al posto della lingua del telefono.</p><p>Per farlo:</p><p>Seleziona la lingua in Scegli una lingua specifica.</p><div class="admonition xdripitem"><p class="admonition-title">Scegli una lingua specifica</p></div><img src="'+k+'" style="zoom:75%;"><p>Porta l&#39;interruttore Forza testo inglese su ON.</p><div class="admonition xdripitem"><p class="admonition-title">Forza testo inglese<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><h3 id="smooth-sensor-noise" tabindex="-1">Liscia il rumore del sensore <a class="header-anchor" href="#smooth-sensor-noise" aria-label="Permalink to &quot;Liscia il rumore del sensore {#smooth-sensor-noise}&quot;">​</a></h3><p>Il lisciamento mostra la curva lisciata (non modifica le letture), utile in caso di misurazioni disturbate.<br> Puoi anche provare il <a href="#graph-smoothing">Lisciamento del Grafico</a> per pulire il grafico.</p><div class="admonition xdripitem"><p class="admonition-title">⚠ Liscia il rumore del sensore<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Cerca di risolvere letture disturbate</p></div><img src="'+n+'" style="zoom:75%;"><h3 id="show-interface-hints" tabindex="-1">Mostra Aiuti Interfaccia <a class="header-anchor" href="#show-interface-hints" aria-label="Permalink to &quot;Mostra Aiuti Interfaccia {#show-interface-hints}&quot;">​</a></h3><p>Dopo la prima installazione di xDrip vedrai dei suggerimenti alla prima apertura di alcune funzioni; puoi disattivare questo comportamento o ripristinarlo.</p><div class="admonition xdripitem"><p class="admonition-title">Mostra Aiuti Interfaccia<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Mostra Suggerimenti / Aiuti descrivendo le funzioni dei vari tasti ecc. Deseleziona e Riseleziona per Reset Iniziale</p></div><img src="'+_+'" style="zoom:75%;"><h3 id="graph-settings" tabindex="-1">Impostazioni grafico <a class="header-anchor" href="#graph-settings" aria-label="Permalink to &quot;Impostazioni grafico {#graph-settings}&quot;">​</a></h3><p>Puoi personalizzare la maggior parte degli elementi mostrati nel grafico principale.</p><div class="admonition xdripitem"><p class="admonition-title">Impostazioni grafico</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_chart_areaspline_grey600_48dp.png" style="width:8%;"> Regola gli elementi del grafico</p></div><h5 id="graph-smoothing" tabindex="-1">Lisciamento del grafico <a class="header-anchor" href="#graph-smoothing" aria-label="Permalink to &quot;Lisciamento del grafico {#graph-smoothing}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Lisciamento del Grafico</p></div><p>Il lisciamento del grafico applica un filtro di lisciamento al grafico per renderlo più facile da seguire (meno rumore).</p><p>È solo un effetto visivo e non influisce sulle letture.</p><div class="admonition xdripitem"><p class="admonition-title">Abilita <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p>Semplifica i grafici lisciando le irregolarità</p></div><img src="'+F+'" style="zoom:76%;"><img src="'+P+'" style="zoom:76%;"><div class="admonition xdripitem"><p class="admonition-title">Visualizzazione non lisciata <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p>Mostra i dati non lisciati anche se il lisciamento è abilitato. Se viene utilizzato un plugin di calibrazione, i dati saranno visualizzati non levigati invece dei dati del plugin.</p></div><h5 id="rewrite-history" tabindex="-1">Riscrivi storico <a class="header-anchor" href="#rewrite-history" aria-label="Permalink to &quot;Riscrivi storico {#rewrite-history}&quot;">​</a></h5><p>Riscrivi Storico ammorbidisce le transizioni dopo l&#39;aggiunta di una nuova calibrazione, per ridurre l&#39;effetto a gradino.<br> Assicurati che sia attivo anche sui follower, per evitare una visualizzazione diversa dei valori di glicemia passati.</p><div class="admonition xdripitem"><p class="admonition-title">Riscrivi Storico <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Dopo aver calibrato, regola il grafico dei dati grezzi recenti in modo da regolarlo con la nuovo valore.</p></div><img src="'+q+'" style="zoom:75%;"><h5 id="widget-range-lines" tabindex="-1">Linee di range del widget <a class="header-anchor" href="#widget-range-lines" aria-label="Permalink to &quot;Linee di range del widget {#widget-range-lines}&quot;">​</a></h5><p>Puoi scegliere di visualizzare le linee dei limiti alto e basso sul widget.</p><div class="admonition xdripitem"><p class="admonition-title">Linee di range del Widget <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Mostra una linea alta e bassa sul widget.</p></div><img src="'+w+'" style="zoom:75%;"><h5 id="main-graph-lines" tabindex="-1">Linee del grafico principale <a class="header-anchor" href="#main-graph-lines" aria-label="Permalink to &quot;Linee del grafico principale {#main-graph-lines}&quot;">​</a></h5><p>Puoi disattivare le linee verticali del tempo nel grafico principale.</p><div class="admonition xdripitem"><p class="admonition-title">Mostra Griglia e Linee Temporali <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Rendi visibili le griglie temporali</p></div><img src="'+I+'" style="zoom:75%;"><p>Puoi disattivare le linee orizzontali della glicemia nel grafico principale.</p><div class="admonition xdripitem"><p class="admonition-title">Mostra Griglia e Linee glicemia <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Rendi visibili le linee valori glicemia</p></div><img src="'+D+'" style="zoom:75%;"><h5 id="filtered-data" tabindex="-1">Dati filtrati <a class="header-anchor" href="#filtered-data" aria-label="Permalink to &quot;Dati filtrati {#filtered-data}&quot;">​</a></h5><p>Il grafico filtrato o lisciato aggiunge un&#39;altra curva al grafico e può facoltativamente creare i dati mancanti.</p><div class="admonition xdripitem"><p class="admonition-title">Mostra Dati Filtrati <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Utile in caso di letture mancanti o non chiare</p></div><div class="admonition xdripitem"><p class="admonition-title">Crea dati filtrati mancanti <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Crea i dati filtrati se necessario</p></div><img src="'+n+'" style="zoom:75%;"><p>Per alcune sorgenti dati (come l&#39;app LL modificata) questo mostrerà i dati grezzi non filtrati, dato che la glicemia visualizzata da xDrip è già filtrata.</p><img src="'+o+'" style="zoom:75%;"><h5 id="raw-data" tabindex="-1">Dati grezzi <a class="header-anchor" href="#raw-data" aria-label="Permalink to &quot;Dati grezzi {#raw-data}&quot;">​</a></h5><p>Dati grezzi che xDrip può visualizzare, se disponibili.</p><div class="admonition xdripitem"><p class="admonition-title">Mostra Dati Grezzi (RAW) <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><p>G4, G5 e G6 con batteria sostituita forniscono dati grezzi.</p><img src="'+C+'" style="zoom:75%;"><p>Oggi i dati grezzi sono visibili soprattutto per i sensori Libre, ma non con questa opzione.<br> Per i dati grezzi dei sensori Libre usa le <a href="./lesscommon.html#advanced-settings-for-libre-2">Impostazioni avanzate per Libre 2</a>.</p><h5 id="basal-information" tabindex="-1">Informazioni sulla basale <a class="header-anchor" href="#basal-information" aria-label="Permalink to &quot;Informazioni sulla basale {#basal-information}&quot;">​</a></h5><p>Se le informazioni sulla basale sono disponibili da una sorgente esterna (<a href="https://androidaps.readthedocs.io/en/latest/index.html" target="_blank" rel="noreferrer">AAPS NSClient</a>), xDrip può visualizzarle.</p><p>In AAPS/NSClient:</p><ul><li><p>Config builder</p></li><li><p>Synchronization - xDrip settings</p></li><li><p>Attiva Send status line to xDrip</p></li></ul><img src="'+A+'" style="zoom:75%;"><p>In xDrip:</p><ul><li>Impostazioni - Impostazioni Meno Usate - attiva Riga di stato extra - attiva <a href="./lesscommon.html#extra-status-line">Stato Esterno</a></li><li>Impostazioni - Impostazioni Inter-app - attiva <a href="./interapp.html#receiving-from-nsclient">Accetta trattamenti</a></li><li>Attiva Mostra TBR basale</li></ul><div class="admonition xdripitem"><p class="admonition-title">Mostra TBR basale <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><img src="'+r+'" style="zoom:75%;"><p>Le informazioni sulla basale vengono caricate anche su <a href="./cloud.html#tidepool">Tidepool</a>.</p><h5 id="target-and-average-lines" tabindex="-1">Linee del target e della media <a class="header-anchor" href="#target-and-average-lines" aria-label="Permalink to &quot;Linee del target e della media {#target-and-average-lines}&quot;">​</a></h5><p>Puoi visualizzare diverse linee di riferimento sul grafico:</p><div class="admonition xdripitem"><p class="admonition-title">Mostra Linea Target su Grafico <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Mostra Media recente su grafico <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Mostra Media Totale su Grafico <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><ol><li>Linea della media delle 8 ore (recente)</li><li>Linea della media delle 24 ore (totale)</li><li>Linea del <a href="./predictions.html#low-level-prediction">target</a></li></ol><img src="'+t+'" style="zoom:75%;"><h5 id="libre-trend" tabindex="-1">Tendenza Libre <a class="header-anchor" href="#libre-trend" aria-label="Permalink to &quot;Tendenza Libre {#libre-trend}&quot;">​</a></h5><p><a href="./3dotsmenu.html#libre-trend">Tendenza Libre</a> attiva un piccolo grafico disponibile nel menu a tre puntini della schermata principale.</p><div class="admonition xdripitem"><p class="admonition-title">Mostra tendenza Libre <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><h5 id="g6-predictions" tabindex="-1">Previsioni G6 <a class="header-anchor" href="#g6-predictions" aria-label="Permalink to &quot;Previsioni G6 {#g6-predictions}&quot;">​</a></h5><p>Predizione G6 è una funzione integrata del trasmettitore Dexcom G6, mostrata con piccoli punti grigi.</p><div class="admonition xdripitem"><p class="admonition-title">Predizione G6 <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Mostra i punti di glicemia predittiva G6</p></div><img src="'+L+'" style="zoom:75%;"><h5 id="smb" tabindex="-1">SMB <a class="header-anchor" href="#smb" aria-label="Permalink to &quot;SMB {#smb}&quot;">​</a></h5><p>Gli SMB sono icone che alleggeriscono il grafico per i trattamenti con microboli. Toccando un SMB, la quantità di insulina compare nella riga informativa.</p><div class="admonition xdripitem"><p class="admonition-title">Mostra icone microbolo <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><img src="'+S+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Medtrum secondario <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><p>Mostra i valori del sensore secondario Medtrum A6.</p><h5 id="trend-momentum" tabindex="-1">Momentum della tendenza <a class="header-anchor" href="#trend-momentum" aria-label="Permalink to &quot;Momentum della tendenza {#trend-momentum}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Mostra Curva Momentum <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><p>Mostra una linea rossa tratteggiata (1), il momentum, che estrapola la tendenza attuale della glicemia per prevedere ipo e iper.<br> È del tutto indipendente dalle <a href="./predictions.html#use-trend-momentum">previsioni</a> (2) e non tiene conto dei modelli dei carboidrati o dell&#39;insulina.</p><img src="'+Q+'" style="zoom:75%;"><h5 id="noise-workings" tabindex="-1">Calcolo del rumore <a class="header-anchor" href="#noise-workings" aria-label="Permalink to &quot;Calcolo del rumore {#noise-workings}&quot;">​</a></h5><p>Informazioni visive aggiuntive sul calcolo del rumore: una linea gialla di cinque punti a destra della curva.</p><div class="admonition xdripitem"><p class="admonition-title">Mostra Letture Disturbate <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><img src="'+o+'" style="zoom:75%;"><h5 id="backfilled-data" tabindex="-1">Dati recuperati <a class="header-anchor" href="#backfilled-data" aria-label="Permalink to &quot;Dati recuperati {#backfilled-data}&quot;">​</a></h5><p>I dati recuperati a posteriori (backfill) possono essere indicati con un punto blu vuoto.</p><div class="admonition xdripitem"><p class="admonition-title">Mostra i dati ricuperati dal sensore <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><img src="'+M+'" style="zoom:75%;"><h5 id="widget-graph" tabindex="-1">Grafico del widget <a class="header-anchor" href="#widget-graph" aria-label="Permalink to &quot;Grafico del widget {#widget-graph}&quot;">​</a></h5><p>Puoi nascondere il grafico nel <a href="./mainUI.html#widget">widget</a> e lasciare solo il valore.</p><div class="admonition xdripitem"><p class="admonition-title">Nascondi grafico widget <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><img src="'+E+'" style="zoom:75%;"><p>Queste due opzioni sono disponibili solo per gli sviluppatori.</p><div class="admonition xdripitem"><p class="admonition-title">Illustra i dati remoti <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><h5 id="y-axis" tabindex="-1">Asse Y <a class="header-anchor" href="#y-axis" aria-label="Permalink to &quot;Asse Y {#y-axis}&quot;">​</a></h5><p>L&#39;asse verticale della schermata principale ha un minimo predefinito di 40 mg/dl (2,22 mmol/l) e un massimo predefinito di 250 mg/dl (13,9 mmol/l).</p><p>Puoi fissare a piacere i valori minimo e massimo dell&#39;asse Y.</p><div class="admonition xdripitem"><p class="admonition-title">Consentire</p></div><p>Per impostazione predefinita, quando le letture sono fuori da questo intervallo, il grafico estende temporaneamente l&#39;intervallo per renderle visibili, poi torna ai valori fissati quando quelle letture escono dallo schermo.</p><p>Se preferisci mantenere fisso l&#39;intervallo dell&#39;asse Y e spostare il grafico in verticale invece di espanderlo, attiva Spostamento auto asse Y.</p><div class="admonition xdripitem"><p class="admonition-title">Spostamento auto asse Y <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> <strong>Abilita:</strong> Sposta il grafico con un asse Y fisso (minimo-massimo) per mostrare le letture fuori intervallo.<br>  <strong>Disabilita:</strong> Espandi l&#39;intervallo dell&#39;asse Y per includere le letture fuori intervallo.</p></div><h3 id="glucose-number-from-filtered" tabindex="-1">Numero di glucosio da Filtrata <a class="header-anchor" href="#glucose-number-from-filtered" aria-label="Permalink to &quot;Numero di glucosio da Filtrata {#glucose-number-from-filtered}&quot;">​</a></h3><p>Il filtraggio può ritardare le letture e non è consigliato.<br> Il filtraggio è integrato nell&#39;hardware per la <a href="./../install/libre2patch.html">sorgente dati app Libre 2 modificata</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Numero di glucosio da Filtrata <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><img src="'+o+'" style="zoom:75%;"><h3 id="bolus-wizard-preview" tabindex="-1">Anteprima della guida automatica di bolo <a class="header-anchor" href="#bolus-wizard-preview" aria-label="Permalink to &quot;Anteprima della guida automatica di bolo {#bolus-wizard-preview}&quot;">​</a></h3><p>La BWP mostra l&#39;insulina attiva (IoB) e suggerisce correzioni in base ai parametri <a href="./predictions.html">predittivi</a> inseriti in xDrip.<br> È solo un&#39;indicazione. Assicurati di aver capito l&#39;EULA prima di usarla.<br> Non seguire mai i suggerimenti quando la glicemia cambia rapidamente.</p><p>L&#39;anteprima della guida automatica di bolo compare solo quando sono presenti carboidrati o insulina.</p><div class="admonition xdripitem"><p class="admonition-title">Mostra l&#39;anteprima della guida automatica di bolo <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Visualizza calcoli Insulina/CHO</p></div><img src="'+N+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Mostra sempre l&#39;anteprima della guida automatica di bolo <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Visualizza sempre i calcoli Insulina/CHO</p></div><p>Se forzi la visualizzazione costante della BWP, suggerirà sempre una correzione (insulina o carboidrati).</p><img src="'+B+'" style="zoom:75%;"><h3 id="high-priority-notifications" tabindex="-1">Notifiche ad alta priorità <a class="header-anchor" href="#high-priority-notifications" aria-label="Permalink to &quot;Notifiche ad alta priorità {#high-priority-notifications}&quot;">​</a></h3><p>Porta il <a href="./misc.html#run-collector-in-foreground">grafico e le notifiche</a> di xDrip in cima all&#39;elenco; disattivandola, scendono.</p><p>Puoi disattivare Notifiche ad alta priorità se preferisci avere xDrip più in basso nell&#39;elenco delle notifiche. Su Android 8.0 e successivi il <a href="./misc.html#run-collector-in-foreground">collector è sempre eseguito in primo piano</a>, quindi Android non metterà xDrip in sospensione.</p><div class="admonition xdripitem"><p class="admonition-title">Notifiche ad alta priorità<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Mostra notifiche e grafico in alto (anche nella schermata di blocco)</p></div><img src="'+s+'" style="zoom:75%;"><h3 id="public-notifications" tabindex="-1">Notifiche pubbliche <a class="header-anchor" href="#public-notifications" aria-label="Permalink to &quot;Notifiche pubbliche {#public-notifications}&quot;">​</a></h3><p>Rende le notifiche visibili sulla schermata di blocco.</p><div class="admonition xdripitem"><p class="admonition-title">Notifiche pubbliche <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><h3 id="enable-reminder-features" tabindex="-1">Abilita funzionalità promemoria <a class="header-anchor" href="#enable-reminder-features" aria-label="Permalink to &quot;Abilita funzionalità promemoria {#enable-reminder-features}&quot;">​</a></h3><p>Attivata per impostazione predefinita: trovi i promemoria nel <a href="./3dotsmenu.html">menu a tre puntini</a> in alto a destra nella schermata principale.</p><div class="admonition xdripitem"><p class="admonition-title">Abilita funzionalità promemoria <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p>Mostra menu e funzionalità di promemoria</p></div><h3 id="always-on-display-settings" tabindex="-1">Impostazioni Sempre Visibile <a class="header-anchor" href="#always-on-display-settings" aria-label="Permalink to &quot;Impostazioni Sempre Visibile {#always-on-display-settings}&quot;">​</a></h3><p>Se il telefono lo supporta, xDrip può usare l&#39;accessibilità di Android per mostrare il suo widget nella schermata sempre attiva (Always On Display).</p><div class="admonition xdripitem"><p class="admonition-title">Abilita Accessibilità xDrip</p><p> Se il telefono ha Always On Display è possibile abilitare il widget xDrip attivando il servizio di accessibilità xDrip dalla pagina Impostazioni di sistema Android.</p></div><img src="'+G+'" style="zoom:75%;"><img src="'+V+'" style="zoom:75%;"><p>Su Android 16 e successivi puoi in alternativa mostrare la glicemia come chip di notifica sulla schermata di blocco / Always On Display, usando la notifica persistente invece dell&#39;accessibilità. Questo si basa sui <a href="./alarms.html#notification-channels">canali di notifica</a>, sempre attivi su Android 8.0 e successivi.</p><div class="admonition xdripitem"><p class="admonition-title">Use AOD chip style <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Display notification chip and lockscreen notification. Android 16+ only</p></div><h3 id="numbered-wall-on-locked-screen" tabindex="-1">Valore della glicemia nella schermata di blocco <a class="header-anchor" href="#numbered-wall-on-locked-screen" aria-label="Permalink to &quot;Valore della glicemia nella schermata di blocco {#numbered-wall-on-locked-screen}&quot;">​</a></h3><p>xDrip può mostrare il valore della glicemia sulla schermata di blocco del telefono.</p><div class="admonition xdripitem"><p class="admonition-title">Valore della glicemia nella schermata di blocco</p></div><p>Questo menu ti permette di personalizzare il numero visualizzato.</p><div class="admonition xdripitem"><p class="admonition-title">Configurazione</p><p>Regolazioni ed anteprima</p></div><p>Vedrai un&#39;anteprima in tempo reale del risultato (123 ⇅)</p><ol><li>Cambia la dimensione del carattere</li><li>Cambia la posizione verticale (o la distanza verticale tra i numeri)</li><li>Cambia la posizione orizzontale (o la distanza orizzontale tra i numeri)</li><li>Cambia il colore del numero</li><li>Seleziona l&#39;immagine di sfondo</li><li>La schermata con il numero vera e propria</li></ol><img src="'+R+'" style="zoom:75%;"><p>Attiva la visualizzazione sulla schermata di blocco per mostrare il numero.</p><div class="admonition xdripitem"><p class="admonition-title">Visualizza sulla schermata di blocco<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Mostra nella schermata di blocco. Android 7 e sopra!</p></div><p>Per impostazione predefinita il numero sulla schermata di blocco usa gli stessi colori della glicemia bassa/nell&#39;intervallo/alta della schermata principale. Puoi forzarlo a usare sempre un unico colore fisso.</p><div class="admonition xdripitem"><p class="admonition-title">Colore testo imposto<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Abilita: Usa sempre il colore di testo selezionato.<br>  Disabilita: Usa i colori della glicemia nella schermata principale (bassa / nell&#39;intervallo / alta).</p></div><div class="admonition xdrip"><p class="admonition-title">Valore della glicemia nella schermata di blocco</p><p>Colori<span style="float:right;width:40px;height:40px;background-color:#FFFFFF;display:inline-block;"></span></p><p>Colore ombra<span style="float:right;width:40px;height:40px;background-color:#000000;display:inline-block;"></span></p></div><p>Attiva e disattiva la funzione per un periodo definito della giornata. Per impostazione predefinita è attiva tutto il giorno.</p><div class="admonition xdripitem"><p class="admonition-title">Accendi</p><p>Scegli l&#39;orario di inizio visualizzazione</p></div><div class="admonition xdripitem"><p class="admonition-title">Orario spegnimento</p><p>Scegli l&#39;orario di fine visualizzazione - setti uguale a l&#39;inizio per averlo sempre visibile</p></div><h3 id="number-icon-in-notification-area" tabindex="-1">Icona numerica nell&#39;area di notifica <a class="header-anchor" href="#number-icon-in-notification-area" aria-label="Permalink to &quot;Icona numerica nell&#39;area di notifica {#number-icon-in-notification-area}&quot;">​</a></h3><p>xDrip può mostrare la glicemia come icona numerica nell&#39;area di notifica in alto a sinistra e nelle notifiche a discesa.</p><img src="'+T+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Icona numerica nell&#39;area di notifica</p></div><p><strong>Prova la funzione prima di usarla, perché su alcuni telefoni può causare un crash.</strong></p><div class="admonition xdripitem"><p class="admonition-title">Esegui test icona numerica</p><p> Le icone numeriche bloccano alcuni telefoni! Esegui il test prima di abilitare la funzione!</p></div><img src="'+O+'" style="zoom:75%;"><p>Durante il test il telefono vibrerà alcune volte e dovresti vedere l&#39;icona della glicemia 123 in alto a sinistra.</p><img src="'+U+'" style="zoom:75%;"><p>Se non funziona, significa che non devi attivare la funzione.</p><p><strong>Una volta confermato il funzionamento</strong> puoi attivarla.</p><div class="admonition xdripitem"><p class="admonition-title">Icona numerica testata<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Quando avrai confermato che il tuo dispositivo può mostrare l&#39;icona numerica</p></div><div class="admonition xdripitem"><p class="admonition-title">Mostra icona numerica piccola<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Mostra il valore della glicemia come icona nella barra di notifica e la schermata di blocco</p></div><h3 id="show-xdrip-on-boot" tabindex="-1">Mostra xDrip all&#39;avvio <a class="header-anchor" href="#show-xdrip-on-boot" aria-label="Permalink to &quot;Mostra xDrip all&#39;avvio {#show-xdrip-on-boot}&quot;">​</a></h3><p>Con questa opzione xDrip si apre automaticamente al riavvio del telefono.</p><p>Può essere utile attivarla se il telefono esegue aggiornamenti e riavvii automatici (sconsigliato) e xDrip non si avvia da solo al riavvio.</p><div class="admonition xdripitem"><p class="admonition-title">Mostra xDrip all&#39;avvio <span class="symbol"><img src="'+p+'" style="zoom:75%;"></span></p><p> Apri automaticamente lo schermo xDrip dopo l&#39;avviamento del telefonino</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',245)])])}const hi=W(j,[["render",K]]);export{ui as __pageData,hi as default};
